/** A form definition (the site's own data: generated by the migration kit from the WordPress form plugin, or written by hand). */
import type { ContentBlock, InlinePart } from "./rich.js";

export type { ContentBlock, InlinePart } from "./rich.js";

/**
 * Field types:
 * - text, email, tel, number, url, date, textarea, select, checkbox — one input each;
 * - radio — one choice of `options`, rendered as a fieldset of radio buttons;
 * - consent — a checkbox whose label may carry links (`labelParts`; `label` is the short name used in errors and
 *   the email, e.g. "Terms and Conditions");
 * - signature — a drawn signature (PNG) or a typed full name (`<name>_typed`); see signature.ts;
 * - content — not an input: text shown in field order (`content`: paragraphs, lists, headings, safe links), e.g.
 *   the terms of a waiver. It is copied into the emailed record so the email shows what the visitor agreed to.
 */
export type FormFieldType = "text" | "email" | "tel" | "number" | "url" | "date" | "textarea" | "select" | "checkbox" | "radio" | "consent" | "signature" | "content";

export interface FormField {
	name: string;
	label: string;
	type: FormFieldType;
	required?: boolean;
	placeholder?: string;
	options?: string[];
	half?: boolean;
	autocomplete?: string;
	/** consent: the label as text runs with safe links (rendered as elements, never as HTML). */
	labelParts?: InlinePart[];
	/** content: the blocks to show. */
	content?: ContentBlock[];
}
export interface FormDefinition {
	id: string;
	title: string;
	submitLabel: string;
	successMessage: string;
	fields: FormField[];
	/** true when the site handles sensitive data: only the fields the owner approved are in `fields`, nothing is stored. */
	sensitive?: boolean;
	/** Shown above the submit button (e.g. "Please don't include health details here"). */
	notice?: string;
	/** After a successful send: hide the form and show the message, or reset it (default). */
	afterSubmit?: "hide" | "reset";
}
